mapper.select:
SELECT id, user_id, token_hash, purpose, expires_at, used, created_at
  FROM email_verification_tokens
 WHERE token_hash = #{tokenHash}

mapper.update:
UPDATE email_verification_tokens
   SET used = TRUE
 WHERE id = #{id}

UPDATE email_verification_tokens
   SET used = TRUE
 WHERE user_id = #{userId}
   AND purpose = #{purpose}
   AND used = FALSE
